changeSet.sql:
DO $$
BEGIN
    IF to_regclass('public.export_template') IS NULL THEN
        RETURN;
    END IF;

    WITH ranked AS (
        SELECT export_template_id,
               version,
               row_number() OVER (PARTITION BY fk_institution_id, lower(name), version ORDER BY export_template_id) AS rn
        FROM export_template
    )
    UPDATE export_template t
    SET version = left(r.version, 40) || '-' || r.rn,
        definition = jsonb_set(t.definition, '{version}', to_jsonb(left(r.version, 40) || '-' || r.rn))
    FROM ranked r
    WHERE t.export_template_id = r.export_template_id AND r.rn > 1;

    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'uk_export_template_institution_name_version') THEN
        ALTER TABLE export_template
            ADD CONSTRAINT uk_export_template_institution_name_version UNIQUE (fk_institution_id, name, version);
    END IF;
END $$;
